import java.util.*;
​
public class Main {
    // 并查集模板
    static int find(int x, int[] parent) {
        if (parent[x] != x) {
            parent[x] = find(parent[x], parent);
        }
        return parent[x];
    }
    // 并查集模板 合并
    static void merge(int a, int b, int[] parent) {
        int rootA = find(a, parent);
        int rootB = find(b, parent);
        int newRoot = Math.min(rootA, rootB);
        parent[rootA] = newRoot;
        parent[rootB] = newRoot;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        List<String> lines = new ArrayList<>();
​
        while (scanner.hasNextLine()) {
            String line = scanner.nextLine().trim();
            if (line.isEmpty()) break;
            lines.add(line);
        }
        scanner.close();
​
        int n = lines.size();
        int[] parent = new int[n + 1];
        for (int i = 1; i <= n; i++) parent[i] = i;
​
        String[][] matrix = new String[n][n];
        for (int i = 0; i < n; i++) {
            matrix[i] = lines.get(i).split(" ");
        }
​
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j].equals("1") && i != j) {
                    merge(i + 1, j + 1, parent);
                }
            }
        }
​
        int count = 0;
        for (int i = 1; i <= n; i++) {
            if (find(i, parent) == i) count++;
        }
​
        System.out.println(count);
    }
}
