vector<string> split(const string& str, char delimiter) {
    vector<string> result;
    stringstream ss(str);
    string item;
​
    // 使用流读取，每次读取到分隔符
    while (getline(ss, item, delimiter)) {
        result.push_back(item);
    }
    return result;
}
