package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 并查集查找
func find(x int, parent []int) int {
    if parent[x] != x {
        parent[x] = find(parent[x], parent)
    }
    return parent[x]
}
​
// 并查集合并
func merge(a, b int, parent []int) {
    rootA := find(a, parent)
    rootB := find(b, parent)
    newRoot := min(rootA, rootB)
    parent[rootA] = newRoot
    parent[rootB] = newRoot
}
​
func min(a, b int) int {
    if a < b {
        return a
    }
    return b
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
    var lines []string
​
    for scanner.Scan() {
        line := strings.TrimSpace(scanner.Text())
        if line == "" {
            break
        }
        lines = append(lines, line)
    }
​
    n := len(lines)
    parent := make([]int, n+1)
    for i := 1; i <= n; i++ {
        parent[i] = i
    }
​
    matrix := make([][]string, n)
    for i := 0; i < n; i++ {
        matrix[i] = strings.Fields(lines[i])
    }
​
    for i := 0; i < n; i++ {
        for j := 0; j < n; j++ {
            if matrix[i][j] == "1" && i != j {
                merge(i+1, j+1, parent)
            }
        }
    }
​
    count := 0
    for i := 1; i <= n; i++ {
        if find(i, parent) == i {
            count++
        }
    }
​
    fmt.Println(count)
}
